import{_ as p,a0 as t,w as o,s as d,ao as r,I as l,x as a,a1 as e,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const y=JSON.parse('{"title":"让你提高效率的 Linux 技巧 | LCTT x X-CMD","titleTemplate":false,"description":"让你提高效率的 Linux 技巧 | LCTT (201809) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"让你提高效率的 Linux 技巧 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"让你提高效率的 Linux 技巧 | LCTT (201809) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201809/20180917 Linux tricks that can save you time and trouble","title":"让你提高效率的 Linux 技巧","tag":"201809","desc":""},"relativePath":"201809/20180917 Linux tricks that can save you time and trouble.md","filePath":"[post].md"}'),c={name:"201809/20180917 Linux tricks that can save you time and trouble.md"};function h(u,s,g,k,b,f){const n=t("Link");return o(),d("div",null,[s[15]||(s[15]=r(`<h1 id="让你提高效率的-linux-技巧" tabindex="-1">让你提高效率的 Linux 技巧 <a class="header-anchor" href="#让你提高效率的-linux-技巧" aria-label="Permalink to “让你提高效率的 Linux 技巧”">​</a></h1><blockquote><p>想要在 Linux 命令行工作中提高效率，你需要使用一些技巧。</p></blockquote><p><img src="https://images.idgesg.net/images/article/2018/09/boy-jumping-off-swing-100772498-large.jpg" alt=""></p><p>巧妙的 Linux 命令行技巧能让你节省时间、避免出错，还能让你记住和复用各种复杂的命令，专注在需要做的事情本身，而不是你要怎么做。以下介绍一些好用的命令行技巧。</p><h3 id="命令编辑" tabindex="-1">命令编辑 <a class="header-anchor" href="#命令编辑" aria-label="Permalink to “命令编辑”">​</a></h3><p>如果要对一个已输入的命令进行修改，可以使用 <code>^a</code>（<code>ctrl + a</code>）或 <code>^e</code>（<code>ctrl + e</code>）将光标快速移动到命令的开头或命令的末尾。</p><p>还可以使用 <code>^</code> 字符实现对上一个命令的文本替换并重新执行命令，例如 <code>^before^after^</code> 相当于把上一个命令中的 <code>before</code> 替换为 <code>after</code> 然后重新执行一次。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ eho hello world  &lt;== 错误的命令</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Command &#39;eho&#39; not found, did you mean:</span></span>
<span class="line"><span></span></span>
<span class="line"><span> command &#39;echo&#39; from deb coreutils</span></span>
<span class="line"><span> command &#39;who&#39; from deb coreutils</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Try: sudo apt install &lt;deb name&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ ^e^ec^        &lt;== 替换</span></span>
<span class="line"><span>echo hello world</span></span>
<span class="line"><span>hello world</span></span></code></pre></div><h3 id="使用远程机器的名称登录到机器上" tabindex="-1">使用远程机器的名称登录到机器上 <a class="header-anchor" href="#使用远程机器的名称登录到机器上" aria-label="Permalink to “使用远程机器的名称登录到机器上”">​</a></h3><p>如果使用命令行登录其它机器上，可以考虑添加别名。在别名中，可以填入需要登录的用户名（与本地系统上的用户名可能相同，也可能不同）以及远程机器的登录信息。例如使用 <code>server_name =&#39;ssh -v -l username IP-address&#39;</code> 这样的别名命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ alias butterfly=”ssh -v -l jdoe 192.168.0.11”</span></span></code></pre></div><p>也可以通过在 <code>/etc/hosts</code> 文件中添加记录或者在 DNS 服务器中加入解析记录来把 IP 地址替换成易记的机器名称。</p><p>执行 <code>alias</code> 命令可以列出机器上已有的别名。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ alias</span></span>
<span class="line"><span>alias butterfly=&#39;ssh -v -l jdoe 192.168.0.11&#39;</span></span>
<span class="line"><span>alias c=&#39;clear&#39;</span></span>
<span class="line"><span>alias egrep=&#39;egrep --color=auto&#39;</span></span>
<span class="line"><span>alias fgrep=&#39;fgrep --color=auto&#39;</span></span>
<span class="line"><span>alias grep=&#39;grep --color=auto&#39;</span></span>
<span class="line"><span>alias l=&#39;ls -CF&#39;</span></span>
<span class="line"><span>alias la=&#39;ls -A&#39;</span></span>
<span class="line"><span>alias list_repos=&#39;grep ^[^#] /etc/apt/sources.list /etc/apt/sources.list.d/*&#39;</span></span>
<span class="line"><span>alias ll=&#39;ls -alF&#39;</span></span>
<span class="line"><span>alias ls=&#39;ls --color=auto&#39;</span></span>
<span class="line"><span>alias show_dimensions=&#39;xdpyinfo | grep &#39;\\&#39;&#39;dimensions:&#39;\\&#39;&#39;&#39;</span></span></code></pre></div><p>只要将新的别名添加到 <code>~/.bashrc</code> 或类似的文件中，就可以让别名在每次登录后都能立即生效。</p><h3 id="冻结、解冻终端界面" tabindex="-1">冻结、解冻终端界面 <a class="header-anchor" href="#冻结、解冻终端界面" aria-label="Permalink to “冻结、解冻终端界面”">​</a></h3><p><code>^s</code>（<code>ctrl + s</code>）将通过执行流量控制命令 XOFF 来停止终端输出内容，这会对 PuTTY 会话和桌面终端窗口产生影响。如果误输入了这个命令，可以使用 <code>^q</code>（<code>ctrl + q</code>）让终端重新响应。所以只需要记住 <code>^q</code> 这个组合键就可以了，毕竟这种情况并不多见。</p><h3 id="复用命令" tabindex="-1">复用命令 <a class="header-anchor" href="#复用命令" aria-label="Permalink to “复用命令”">​</a></h3><p>Linux 提供了很多让用户复用命令的方法，其核心是通过历史缓冲区收集执行过的命令。复用命令的最简单方法是输入 <code>!</code> 然后接最近使用过的命令的开头字母；当然也可以按键盘上的向上箭头，直到看到要复用的命令，然后按回车键。还可以先使用 <code>history</code> 显示命令历史，然后输入 <code>!</code> 后面再接命令历史记录中需要复用的命令旁边的数字。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>!! &lt;== 复用上一条命令</span></span>
<span class="line"><span>!ec &lt;== 复用上一条以 “ec” 开头的命令</span></span>
<span class="line"><span>!76 &lt;== 复用命令历史中的 76 号命令</span></span></code></pre></div><h3 id="查看日志文件并动态显示更新内容" tabindex="-1">查看日志文件并动态显示更新内容 <a class="header-anchor" href="#查看日志文件并动态显示更新内容" aria-label="Permalink to “查看日志文件并动态显示更新内容”">​</a></h3><p>使用形如 <code>tail -f /var/log/syslog</code> 的命令可以查看指定的日志文件，并动态显示文件中增加的内容，需要监控向日志文件中追加内容的的事件时相当有用。这个命令会输出文件内容的末尾部分，并逐渐显示新增的内容。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ tail -f /var/log/auth.log</span></span>
<span class="line"><span>Sep 17 09:41:01 fly CRON[8071]: pam_unix(cron:session): session closed for user smmsp</span></span>
<span class="line"><span>Sep 17 09:45:01 fly CRON[8115]: pam_unix(cron:session): session opened for user root</span></span>
<span class="line"><span>Sep 17 09:45:01 fly CRON[8115]: pam_unix(cron:session): session closed for user root</span></span>
<span class="line"><span>Sep 17 09:47:00 fly sshd[8124]: Accepted password for shs from 192.168.0.22 port 47792</span></span>
<span class="line"><span>Sep 17 09:47:00 fly sshd[8124]: pam_unix(sshd:session): session opened for user shs by</span></span>
<span class="line"><span>Sep 17 09:47:00 fly systemd-logind[776]: New session 215 of user shs.</span></span>
<span class="line"><span>Sep 17 09:55:01 fly CRON[8208]: pam_unix(cron:session): session opened for user root</span></span>
<span class="line"><span>Sep 17 09:55:01 fly CRON[8208]: pam_unix(cron:session): session closed for user root</span></span>
<span class="line"><span>        &lt;== 等待显示追加的内容</span></span></code></pre></div><h3 id="寻求帮助" tabindex="-1">寻求帮助 <a class="header-anchor" href="#寻求帮助" aria-label="Permalink to “寻求帮助”">​</a></h3><p>对于大多数 Linux 命令，都可以通过在输入命令后加上选项 <code>--help</code> 来获得这个命令的作用、用法以及它的一些相关信息。除了 <code>man</code> 命令之外， <code>--help</code> 选项可以让你在不使用所有扩展选项的情况下获取到所需要的内容。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mkdir --help</span></span>
<span class="line"><span>Usage: mkdir [OPTION]... DIRECTORY...</span></span>
<span class="line"><span>Create the DIRECTORY(ies), if they do not already exist.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Mandatory arguments to long options are mandatory for short options too.</span></span>
<span class="line"><span> -m, --mode=MODE set file mode (as in chmod), not a=rwx - umask</span></span>
<span class="line"><span> -p, --parents no error if existing, make parent directories as needed</span></span>
<span class="line"><span> -v, --verbose print a message for each created directory</span></span>
<span class="line"><span> -Z set SELinux security context of each created directory</span></span>
<span class="line"><span> to the default type</span></span>
<span class="line"><span> --context[=CTX] like -Z, or if CTX is specified then set the SELinux</span></span>
<span class="line"><span> or SMACK security context to CTX</span></span>
<span class="line"><span> --help display this help and exit</span></span>
<span class="line"><span> --version output version information and exit</span></span>
<span class="line"><span></span></span>
<span class="line"><span>GNU coreutils online help: &lt;http://www.gnu.org/software/coreutils/&gt;</span></span>
<span class="line"><span>Full documentation at: &lt;http://www.gnu.org/software/coreutils/mkdir&gt;</span></span>
<span class="line"><span>or available locally via: info &#39;(coreutils) mkdir invocation&#39;</span></span></code></pre></div><h3 id="谨慎删除文件" tabindex="-1">谨慎删除文件 <a class="header-anchor" href="#谨慎删除文件" aria-label="Permalink to “谨慎删除文件”">​</a></h3><p>如果要谨慎使用 <code>rm</code> 命令，可以为它设置一个别名，在删除文件之前需要进行确认才能删除。有些系统管理员会默认使用这个别名，对于这种情况，你可能需要看看下一个技巧。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ rm -i    &lt;== 请求确认</span></span></code></pre></div><h3 id="关闭别名" tabindex="-1">关闭别名 <a class="header-anchor" href="#关闭别名" aria-label="Permalink to “关闭别名”">​</a></h3><p>你可以使用 <code>unalias</code> 命令以交互方式禁用别名。它不会更改别名的配置，而仅仅是暂时禁用，直到下次登录或重新设置了这一个别名才会重新生效。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ unalias rm</span></span></code></pre></div><p>如果已经将 <code>rm -i</code> 默认设置为 <code>rm</code> 的别名，但你希望在删除文件之前不必进行确认，则可以将 <code>unalias</code> 命令放在一个启动文件（例如 <code>~/.bashrc</code>）中。</p><h3 id="使用-sudo" tabindex="-1">使用 sudo <a class="header-anchor" href="#使用-sudo" aria-label="Permalink to “使用 sudo”">​</a></h3><p>如果你经常在只有 root 用户才能执行的命令前忘记使用 <code>sudo</code>，这里有两个方法可以解决。一是利用命令历史记录，可以使用 <code>sudo !!</code>（使用 <code>!!</code> 来运行最近的命令，并在前面添加 <code>sudo</code>）来重复执行，二是设置一些附加了所需 <code>sudo</code> 的命令别名。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ alias update=’sudo apt update’</span></span></code></pre></div><h3 id="更复杂的技巧" tabindex="-1">更复杂的技巧 <a class="header-anchor" href="#更复杂的技巧" aria-label="Permalink to “更复杂的技巧”">​</a></h3><p>有时命令行技巧并不仅仅是一个别名。毕竟，别名能帮你做的只有替换命令以及增加一些命令参数，节省了输入的时间。但如果需要比别名更复杂功能，可以通过编写脚本、向 <code>.bashrc</code> 或其他启动文件添加函数来实现。例如，下面这个函数会在创建一个目录后进入到这个目录下。在设置完毕后，执行 <code>source .bashrc</code>，就可以使用 <code>md temp</code> 这样的命令来创建目录立即进入这个目录下。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>md () { mkdir -p &quot;$@&quot; &amp;&amp; cd &quot;$1&quot;; }</span></span></code></pre></div><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>使用 Linux 命令行是在 Linux 系统上工作最有效也最有趣的方法，但配合命令行技巧和巧妙的别名可以让你获得更好的体验。</p><hr>`,42)),l("p",null,[s[1]||(s[1]=a("via: ",-1)),e(n,{href:"https://www.networkworld.com/article/3305811/linux/linux-tricks-that-even-you-can-love.html"},{default:i(()=>[...s[0]||(s[0]=[a("https://www.networkworld.com/article/3305811/linux/linux-tricks-that-even-you-can-love.html",-1)])]),_:1})]),l("p",null,[s[6]||(s[6]=a("作者：",-1)),e(n,{href:"https://www.networkworld.com/author/Sandra-Henry_Stocker/"},{default:i(()=>[...s[2]||(s[2]=[a("Sandra Henry-Stocker",-1)])]),_:1}),s[7]||(s[7]=a(" 选题：",-1)),e(n,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[3]||(s[3]=[a("lujun9972",-1)])]),_:1}),s[8]||(s[8]=a(" 译者：",-1)),e(n,{href:"https://github.com/HankChow"},{default:i(()=>[...s[4]||(s[4]=[a("HankChow",-1)])]),_:1}),s[9]||(s[9]=a(" 校对：",-1)),e(n,{href:"https://github.com/wxy"},{default:i(()=>[...s[5]||(s[5]=[a("wxy",-1)])]),_:1})]),l("p",null,[s[12]||(s[12]=a("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[10]||(s[10]=[a("LCTT",-1)])]),_:1}),s[13]||(s[13]=a(" 原创编译，",-1)),e(n,{href:"https://linux.cn/"},{default:i(()=>[...s[11]||(s[11]=[a("Linux中国",-1)])]),_:1}),s[14]||(s[14]=a(" 荣誉推出",-1))])])}const C=p(c,[["render",h]]);export{y as __pageData,C as default};
